  <section class="summary" id="summary" aria-labelledby="sum-h">
    <h2 id="sum-h">예약 요약</h2>
    <dl>
      <div class="row" data-row="service"><dt>진료 항목</dt><dd class="empty" id="s-service">선택 전</dd></div>
      <div class="row" data-row="vet"><dt>수의사</dt><dd class="empty" id="s-vet">선택 전</dd></div>
