<details class="proto-note">
  <summary>프로토타입 메모: API 시간대 검증 결과(실서비스 UI 아님)</summary>
  <ul id="audit"></ul>
</details>

<script>
/* ---------- 데이터 ---------- */
const DAY = "목";
const DAY_LABEL = "목요일"; // API가 실제 날짜를 주면 "N월 N일(목)"으로 교체
const ADDRESS = "예시시 해안로 12";
const HOURS = {open:"09:00", close:"17:00", lunchStart:"12:00", lunchEnd:"13:00"};

const SERVICES = [
  {id:"checkup", name:"건강검진 진료", min:30, price:65000,  priceFrom:false, vets:"all",   common:true},
  {id:"vaccine", name:"예방접종",     min:15, price:40000,  priceFrom:false, vets:"all",   common:true},
  {id:"scaling", name:"스케일링",     min:90, price:280000, priceFrom:true,  vets:["lee"], common:false},
  {id:"exotic",  name:"특수동물 진료", min:45, price:85000,  priceFrom:false, vets:["lee"], common:false}
];
const VETS = [
  {id:"lee",  apiName:"이영희", name:"이영희", title:"원장",   days:["화","목","토"], daysLabel:"화·목·토"},
  {id:"park", apiName:"박영수", name:"박영수", title:"수의사", days:["월","화","수","목","금","토"], daysLabel:"월~토"}
];
const API_SLOTS = [
  {"vet":"박영수","service":"특수동물 진료","start":"10:00"},
  {"vet":"이영희","service":"특수동물 진료","start":"11:00"},
  {"vet":"이영희","service":"스케일링","start":"11:30"},
  {"vet":"박영수","service":"건강검진 진료","start":"12:30"},
  {"vet":"박영수","service":"건강검진 진료","start":"14:00"},
  {"vet":"이영희","service":"건강검진 진료","start":"16:45"}
];

/* ---------- 유틸 ---------- */
const $ = id => document.getElementById(id);
const toMin = t => { const [h,m] = t.split(":").map(Number); return h*60+m; };
const hhmm = m => String(Math.floor(m/60)).padStart(2,"0")+":"+String(m%60).padStart(2,"0");
const won = n => n.toLocaleString("ko-KR")+"원";
const priceText = s => won(s.price)+(s.priceFrom ? "부터" : "");
const vetLabel = v => `${v.name} ${v.title}`;
const svcById = id => SERVICES.find(s => s.id === id);
const vetById = id => VETS.find(v => v.id === id);
const canTreat = (svc, vet) => svc.vets === "all" || svc.vets.includes(vet.id);
const eunNeun = w => { const c = w.charCodeAt(w.length-1)-0xAC00; return w+(c>=0 && c<11172 && c%28 ? "은" : "는"); };

/* ---------- 시간대 검증: 실제로 예약 가능한 것만 남김 ---------- */
function validate(raw){
  const svc = SERVICES.find(s => s.name === raw.service);
  const vet = VETS.find(v => v.apiName === raw.vet);
  if(!svc || !vet) return "알 수 없는 진료 항목 또는 수의사";
  if(!canTreat(svc, vet)) return `담당 불가 — ${eunNeun(svc.name)} 이영희 원장 전담`;
  if(!vet.days.includes(DAY)) return "근무일 아님";
  const s = toMin(raw.start), e = s + svc.min;
  if(s < toMin(HOURS.open) || e > toMin(HOURS.close)) return `${hhmm(s)}–${hhmm(e)} — 진료 종료(17:00) 이후에 끝남`;
  if(s < toMin(HOURS.lunchEnd) && e > toMin(HOURS.lunchStart)) return `${hhmm(s)}–${hhmm(e)} — 점심시간과 겹침`;
  return null;
}
const AUDIT = API_SLOTS.map(raw => ({raw, reason: validate(raw)}));
const SLOTS = AUDIT.filter(a => !a.reason).map(({raw}) => {
  const svc = SERVICES.find(s => s.name === raw.service), vet = VETS.find(v => v.apiName === raw.vet);
  const start = toMin(raw.start);
  return {id:`${vet.id}-${svc.id}-${raw.start}`, svc:svc.id, vet:vet.id, start, end:start+svc.min};
}).sort((a,b) => a.start - b.start);
const slotById = id => SLOTS.find(s => s.id === id);

/* ---------- 상태 ---------- */
const state = {step:1, service:null, vet:null, slot:null, ack:false};
const STEP_NAMES = ["진료 항목","수의사","시간","예약 확인","예약 완료"];

/* ---------- 렌더 ---------- */
function optionHTML(name, value, title, right, meta, big){
  return `<label class="option${big?" big":""}"><input type="radio" name="${name}" value="${value}">`+
    `<span class="opt-main"><span class="opt-title"><span>${title}</span><span>${right}</span></span>`+
    `<span class="opt-meta">${meta}</span></span></label>`;
}
function availText(n){ return n ? `${DAY_LABEL} ${n}개 시간` : `${DAY_LABEL} 가능 시간 없음`; }
function check(name, value){ document.querySelectorAll(`input[name="${name}"]`).forEach(i => i.checked = i.value === value); }

function renderServices(){
  const meta = s => {
    const who = s.vets === "all" ? "모든 수의사" : s.vets.map(id => vetLabel(vetById(id))).join(", ");
    const n = SLOTS.filter(x => x.svc === s.id).length;
    return `${s.min}분 · ${who} · ${availText(n)}${s.priceFrom ? "<br>최종 금액은 진료 후 안내" : ""}`;
  };
  $("svc-common").innerHTML = SERVICES.filter(s => s.common).map(s => optionHTML("service", s.id, s.name, priceText(s), meta(s), true)).join("");
  $("svc-other").innerHTML  = SERVICES.filter(s => !s.common).map(s => optionHTML("service", s.id, s.name, priceText(s), meta(s), false)).join("");
}

function renderVets(){
  const svc = svcById(state.service);
  const eligible = VETS.filter(v => canTreat(svc, v));
  let html = "";
  if(eligible.length > 1){
    const n = SLOTS.filter(s => s.svc === svc.id).length;
    html += optionHTML("vet", "any", "아무 수의사나 가능", "", `모든 수의사의 시간을 보여 드려요 · ${availText(n)}`, true);
  }
  html += eligible.map(v => {
    const n = SLOTS.filter(s => s.svc === svc.id && s.vet === v.id).length;
    return optionHTML("vet", v.id, vetLabel(v), "", `${v.daysLabel} 근무 · ${availText(n)}`, false);
  }).join("");
  $("vet-list").innerHTML = html;
  $("vet-hint").textContent = eligible.length > 1
    ? "원하는 수의사가 없으면 그대로 ‘다음’을 누르세요."
    : `${eunNeun(svc.name)} ${vetLabel(eligible[0])}만 진료합니다.`;
  if(!state.vet){
    state.vet = eligible.length > 1 ? "any" : eligible[0].id;
    updateSummary(["vet"], "수의사 기본값 " + (state.vet === "any" ? "아무 수의사나 가능" : vetLabel(eligible[0])));
  }
  check("vet", state.vet);
}

function currentSlots(){
  return SLOTS.filter(s => s.svc === state.service && (state.vet === "any" || s.vet === state.vet));
}
function renderSlots(){
  const svc = svcById(state.service);
  const list = currentSlots();
  if(state.slot && !list.some(s => s.id === state.slot)) state.slot = null;
  $("slot-list").innerHTML = list.map(s =>
    option
